    # Demos establish that each frame gets the color of its sparse, same-colored guide marks.
    # In this stream the frame's nearby guide hue is determined by matching guide points
    # to the frame's nearest outside edge and repeating their checkerboard arrangement.
    for color,a,b,x,y in frames:
        for c in range(x,y+1): out[a][c]=out[b][c]=color
